// Modern C++ features
class ModernClass {
private:
    int value{0};  // In-class initializer

public:
    // Constructor with delegating and uniform initialization
    ModernClass() : ModernClass(42) {}
    ModernClass(int v) : value{v} {}

    // Move semantics
    ModernClass(ModernClass&& other) noexcept = default;

    // Constexpr function
    constexpr int getValue() const { return value; }
};

